import{_ as t,H as a,f as r,i as _}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"第二季回归 | 这次，我们一起实战解析真实世界的编译器","description":"","frontmatter":{},"headers":[],"relativePath":"编译原理之美/第二季回归-这次，我们一起实战解析真实世界的编译器.md","filePath":"编译原理之美/第二季回归-这次，我们一起实战解析真实世界的编译器.md","lastUpdated":1779821665000}'),p={name:"编译原理之美/第二季回归-这次，我们一起实战解析真实世界的编译器.md"};function n(i,e,m,s,o,c){return a(),r("div",null,[...e[0]||(e[0]=[_('<h1 id="第二季回归-这次-我们一起实战解析真实世界的编译器" tabindex="-1">第二季回归 | 这次，我们一起实战解析真实世界的编译器 <a class="header-anchor" href="#第二季回归-这次-我们一起实战解析真实世界的编译器" aria-label="Permalink to &quot;第二季回归 | 这次，我们一起实战解析真实世界的编译器&quot;">​</a></h1><p>你好，我是宫文学，这次我带着一门全新的课程 <a href="https://time.geekbang.org/column/intro/314?utm_term=zeusULN89&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=314-presell&amp;utm_content=diyijijiacan0601" target="_blank" rel="noreferrer">《编译原理实战课》</a> 回来了。</p><p>我在《编译原理之美》的开篇词中就说过，编译原理与你的工作息息相关，无论你是前端工程师、后端工程师，还是运维工程师，不论你是初级工程师还是职场老手，编译技术都能给你帮助，甚至让你提升一个级别。</p><p>在第一季，我带你一起梳理了编译技术最核心的概念、理论和算法，帮你构建出了一条相对平坦的学习曲线，让你能够理解大多数技术人都很畏惧的编译原理核心知识。在课程更新的过程中，我发现有很多同学都会有这样一个疑问，那就是：“我确实理解了编译技术的相关原理、概念、算法等，但是有没有更直接的方式，能让我更加深入地把知识与实践相结合呢？”</p><p>所以，在 <a href="https://time.geekbang.org/column/intro/314?utm_term=zeusULN89&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=314-presell&amp;utm_content=diyijijiacan0601" target="_blank" rel="noreferrer">第二季</a>，我会以实战的方式带你挑战编译原理这个领域，也就是带你一起解析真实世界中的编译器。在课程中，我会带你研究不同语言的编译器的源代码，一起跟踪它们的运行过程，分析编译过程的每一步是如何实现的，并会对有特点的编译技术点加以分析和点评。在这个过程中，你会获得对编译器的第一手的理解。</p><p>另外，我还会带你分析和总结前面已经研究过的编译器，让你对现代语言的编译器的结构、所采用的算法以及设计上的权衡，都获得比较真切的认识。</p><p>下面是专栏的目录：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86%E4%B9%8B%E7%BE%8E/images/243248/0cd5596b9f86ddc49f4ef009cf363e3e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86%E4%B9%8B%E7%BE%8E/images/243248/0cd5596b9f86ddc49f4ef009cf363e3e.jpg" alt=""></a></p><p>为了感谢老同学， 我还准备了一个「专属福利」：</p><p>6月1日课程上线，我会送你一张15元专属优惠券，可与限时优惠同享，有效期48小时，建议尽早使用。</p><p><strong>点击下方图片</strong>，立即免费试读新专栏。</p>',11)])])}const d=t(p,[["render",n]]);export{l as __pageData,d as default};
